sys_variable_value.value:
(function execute(inputs, outputs) {
    try {
        var payloadsList = [];
        // Dates already present in Xero for this user/task/week.
        var existingDates = (inputs.existing_dates || '').split(',');
        var timeCardGR = new GlideRecord('time_card');

        if (!timeCardGR.get(inputs.time_card_id)) {
            throw new Error('Time card not found.');
        }

        var weekStartStr = timeCardGR.getValue('week_starts_on');

        if (!weekStartStr) {
            throw new Error('Time card is missing week_starts_on.');
        }

        // Read notes from oldest to newest.
        var notesList = [];
        var journalGR = new GlideRecord('sys_journal_field');

        journalGR.addQuery('element_id', timeCardGR.getUniqueValue());
        journalGR.addQuery('element', 'notes');
        journalGR.orderBy('sys_created_on');
        journalGR.orderBy('sys_id');
        journalGR.query();

        while (journalGR.next()) {
            var noteText = (journalGR.getValue('value') || '')
                .replace(/^\s+|\s+$/g, '');

            if (noteText) {
                notesList.push(noteText);
            }
        }

        // Number each note and separate them with a pipe.
        var formattedNotes = [];

        for (var n = 0; n < notesList.length; n++) {
            formattedNotes.push(
                'Note ' + (n + 1) + ': ' + notesList[n]
            );
        }

        // R3: escape quotes, backslashes and line breaks, because the
        // description is inserted inside "..." in the REST body template.
        var timeCardComment =
            JSON.stringify(formattedNotes.join(' | ')).slice(1, -1);

        // Map daily fields from the time card's real week start day,
        // so it works with time sheet policies starting on any day.
        var dayFields = ['sunday', 'monday', 'tuesday', 'wednesday',
                         'thursday', 'friday', 'saturday'];
        var startDow = new GlideDateTime(
            weekStartStr.substring(0, 10) + ' 12:00:00'
        ).getDayOfWeekUTC() % 7; // 0 = Sunday ... 6 = Saturday

        for (var i = 0; i < 7; i++) {
            var fieldName = dayFields[(startDow + i) % 7];
            var hours =
                parseFloat(timeCardGR.getValue(fieldName)) || 0;

            if (hours <= 0) {
                continue;
            }

            // Calculate dates entirely in UTC.
            var gdt = new GlideDateTime(
                weekStartStr.substring(0, 10) + ' 09:00:00'
            );

            gdt.addDaysUTC(i);

            var dateOnly = gdt.getDate().getValue();

            // Skip days already created in Xero.
            if (existingDates.indexOf(dateOnly) > -1) {
                continue;
            }

            var dateUtcFormatted =
                dateOnly + 'T09:00:00.0000000+00:00';

            payloadsList.push({
                dateUtc: dateUtcFormatted,
                duration: String(Math.round(hours * 60)),
                description: timeCardComment
            });
        }

        // Return the list as Array.Object. An empty list is valid
        // and the flow's For Each runs 0 times.
        outputs.entries = payloadsList;

    } catch (ex) {
        gs.error('[Xero time card] Error: ' + ex.message);
        throw ex;
    }
})(inputs, outputs);

